nanodns_migrate_body:
  "カスタムリゾルバー、上書き、例外、コメント、パスをすべて保持し、不足している nanoDNS 0.4 設定の追加と古い Yandex.DNS アドレスの修正だけを行います。エディターを確認してから保存してください。",
