// 人間向けに整形したエラーメッセージ — lib/humanizeError.ts が表示します。{placeholders}
// は実行時に置換されるため、翻訳時はそのまま残してください。
err_unmount_busy:
  "アンマウントできません: このイメージ内のゲームが現在 PS5 で実行中です。ゲームを終了し（PS Home → ゲームを閉じる）、もう一度お試しください。",
