  picker_grant_hint:
    "ゲームフォルダや .zip をアップロードするには、PS5 Upload にファイルの読み取り許可が必要です。下をタップして「すべてのファイルの管理を許可」を有効にし、戻ってから「再試行」をタップしてください。",
