"fpkg.about": "ゲームフォルダー、または .exfat／.ffpkg のマウントイメージを指定してください。コンバーターはツリーを読み取り、起動できるパッケージに必要なものがすべてそろっているか確認し、デバッグ形式の .pkg を出力フォルダーに書き込みます。",
"fpkg.aboutWhere": "変換は本体ではなく、エンジンを動かしているマシン（このコンピューター、Docker ホスト、Android 端末）で実行されます。パッケージをインストールするまで本体には何も届きません。インストールは、このコンピューターからのストリーム、または先に PS5 へアップロードする方法で行います。",
"fpkg.aboutSource": "ソースはすでに復号済みのゲームツリーである必要があります。製品版のインストールはここでは展開できず、それを選んだ場合は下のチェックで知らせます。",
"fpkg.aboutFake": "結果はフェイクパッケージなので、インストール前に本体でフェイクパッケージ対応を読み込んでおく必要があります：kstuff（PS5 フェイクパッケージ対応のビルド）、a53_ppr_install_fast.elf、shadowmountplus.elf をこの順番で。「パッケージをインストール」でも、インストールボタンの横に同じことが書かれています。",
"fpkg.aboutChecks": "チェック内容",
