"fpkg.checkParam": "sce_sys/param.json があり、sce_sys/param.sfo がないこと。param.sfo があると本体の起動経路が PS4 用になります。",
"fpkg.checkIcons": "36 文字のコンテンツ ID、両方のアイコン、権利モジュール sce_sys/about/right.sprx。",
"fpkg.checkDrm": "パッケージの DRM 値が標準であること。無料またはアップグレード可能な値だと本体がタイトルをロックします。書き換えるのはパッケージ内だけで、元のファイルには一切触れません。",
