health_junk_explain_v2: "ps5upload が生成し、もう不要になったもの: 転送の中断で残った未完成のファイル、一時フォルダーに 1 時間以上残っているパッケージのコピー、古い速度テストのファイル。調べるのは ps5upload 自身のフォルダーだけで、ゲーム、パッケージ、セーブデータには一切触れません。",
home_health_checking: "すべて正常か確認しています…",
home_health_desc: "この本体について、ポート、接続、ストレージ、セットアップを確認します。",
