about_feat_console_body: "ネットワーク経由での休止モード、再起動、シャットダウン、起動に加え、実行中のプロセス、ファンカーブ、ハードウェアの概要。",
about_feat_console_title: "本体の操作",
about_feat_convert_body: "ゲームフォルダーやイメージをインストール可能なパッケージに、またはフォルダーを ShadowMount+ がマウントするゲームイメージに変換します。",
about_feat_convert_title: "ゲームを変換",
about_feat_install_body: "PS4 の .pkg と PS5 のフェイクパッケージ（本編、アップデート、DLC）を、このコンピューター、NAS 共有、USB ドライブ、またはリンクからインストールします。PS5 がある経路を拒否した場合は、アプリが別の経路を提案します。",
about_feat_install_title: "パッケージをインストール",
about_feat_payloads_body: "カタログや自分のファイルからペイロード ELF を本体のローダーに送信します。1 つずつでも、プレイリストとしてまとめてでも送れます。",
about_feat_payloads_title: "ペイロード",
