activity_cancel_tooltip: "この操作をキャンセル",
activity_clear_shown_confirm_body: "ここに表示されている終了済みの項目（完了、失敗、停止）を削除します。他の本体の履歴と実行中のものは残ります。1 行だけ削除するには、その行のゴミ箱ボタンを使ってください。",
activity_clear_shown_confirm_title: "この履歴を消去しますか？",
