always_overwrite_hint_v2: "アップロード画面で、転送先にすでにファイルがある場合の確認を省略します。オフのままにすると「上書き / 再開 / キャンセル」の確認が表示されます。",
audit_empty_v2: "まだ記録はありません。電源操作（起動、休止モード、再起動、シャットダウン）、削除、登録解除、アンインストール、インストールを行うと、ここに表示されます。",
audit_log_description_v3: "電源操作、削除、登録解除、アンインストール、インストールの記録で、このコンピューター上のこのアプリ内に保存されます。最新の 256 件が保持され、古いものは順に消えます。消去ボタンはありませんが、アプリのデータやブラウザーのストレージを消去すると消えます。表示されるのは最新の 100 件です。",
