backup_explain_v2: "ファイルを本体自身のストレージ上のスナップショットにコピーし、後で元に戻せるようにします。下のよく使う項目から選ぶか、パスを入力してください。",
backup_limit_depth: "選んだフォルダーから {n} 階層より深いフォルダーはスキップされます。",
backup_limit_flatten: "ファイルはパス中の / をすべて _ に置き換えた名前で保存されるため、異なる 2 つのパスが同じ名前になることがあり（a/b_c と a_b/c）、その場合は片方しか残りません。",
backup_limit_keep: "同じ名前のスナップショットは最新の {n} 件だけが保持されます。新しく作ると最も古いものが削除されます。",
backup_subtitle_v3: "ファイルやフォルダーを PS5 本体に保存されるスナップショットにコピーし、後で元に戻せます。このコンピューターには何もコピーされません。ゲームのセーブには「セーブデータ」を使ってください。",
bandwidth_cap_clear: "制限を解除",
bandwidth_cap_off_hint_v2: "制限なし。アップロードで Wi-Fi/LAN が飽和して他のデバイスが遅くなる場合に設定してください。アップロード画面、キュー、ファイルからのすべてのアップロードに、次に開始するものから適用されます。",
bandwidth_cap_on_hint_v2: "次に開始するアップロードから、すべてのアップロードの合計が約 {n} MB/s に抑えられます。0 にすると制限が解除されます。",
beta_features_hint_v2: "開発中の画面があれば、それをサイドバーに追加します。使用はできますがまだ信頼性が十分でなく、変更または削除されることがあります。",
bringup_desc_v2: "ペイロードでプレイリストを設定したら、起動のたびに使えます：起動用プレイリスト（kstuff、ShadowMount+…）を実行し、手順 2 と同じ方法でヘルパーを送信してから、自動ローダーのプレイリストを実行します。",
changelog_description_v2: "このバージョンまでのすべての ps5upload バージョンのリリースノートで、アプリに同梱されています。より新しいリリースとそのダウンロードは GitHub にあります。",
cheats_reapply: "実行中のゲームに再適用",
