companion_suggest_body_v2: "ps5upload は kstuff（カーネルエクスプロイト）、ShadowMount+（ゲームバックアップの自動マウント）など、多数の自作ペイロードと連携します。ペイロード → カタログからワンクリックで送信できます。",
companion_suggest_open_payloads: "ペイロードを開く",
connection_first_run_nudge_body_v2: "セットアップウィザードは kstuff と ShadowMount+ をダウンロードして送信し、続けてヘルパーを正しい順序で送信します。本体がすでに kstuff を自分で読み込む場合（オートローダー、etaHEN）は、下の手順 2 でヘルパーだけを送信します。",
connection_step2_which: "ここではヘルパーだけを送信します。kstuff と ShadowMount+ も読み込むには、初回はセットアップウィザードを、プレイリストを設定した後は起動のたびに下のクイック起動を使ってください。",
connection_step3_hint_v2: "アップロードに移動して、ゲームフォルダー、.exfat イメージ、または .ffpkg イメージをドロップしてください。アップロードしたイメージとフォルダーは ゲーム → ゲームファイル に表示され、「マウント」で PS5 のホーム画面に表示されます。.pkg パッケージをインストールするには「パッケージをインストール」を使ってください。",
console_snapshots: "本体のスナップショット",
fakelibs_scan_body_all: "設定済みのすべての本体（{consoles} 台）で、すでにバックポートされたゲームからライブラリを収集します。すべて 1 つの共有コーパスにまとめられます。",
fakelibs_set_remove_confirm_action: "削除",
fakelibs_set_remove_confirm_body: "「{label}」はライブラリコーパスから削除されます。すでにバックポートしたゲームはライブラリを保持しますが、このセットが必要なゲームをバックポートするには、もう一度追加する必要があります。",
fakelibs_set_remove_confirm_title: "このライブラリセットを削除しますか？",
first_run_description_v3: "ほとんどの環境で必要なものを正しい順序で読み込みます：kstuff（フェイクパッケージのインストールと実行を可能にする）、ShadowMount+（ゲームイメージやフォルダーを PS5 のホーム画面に表示する）、そして ps5upload 自身のヘルパーです。PS5 の再起動後、接続画面でこのウィザードが再び提案されます。",
