reset_confirm_body_browser: "このブラウザーが PS5Upload のために保存しているすべての設定と状態を消去し、ページを初期状態で再読み込みします。サーバー上のエンジン自身のデータ（本体のペアリング、コレクション、保存したサーバー、バックポート用ライブラリ、インストール履歴、ログ）には影響せず、PS5 上のものにも影響しません。元に戻すことはできません。",
reset_confirm_body_v2: "PS5Upload のローカルデータをすべて完全に削除します：設定、保存した PS5 とそのペアリング、コレクション、保存したサーバーとそのパスワード、バックポート用ライブラリ、インストール履歴、ジョブとイベント、アクティビティ / キューの履歴、ログ、ペイロードのキャッシュ、クラッシュレポート。PS5 上のものには一切触れません。アプリは初期状態で再読み込みされます。元に戻すことはできません。",
reset_hint_browser: "このブラウザーが PS5Upload のために保存しているすべての設定と状態を消去して、最初からやり直します。エンジンがサーバー上に保存しているもの（本体のペアリング、コレクション、保存したサーバー、バックポート用ライブラリ、インストール履歴、ログ）には影響せず、PS5 上のものにも影響しません。",
reset_hint_v2: "PS5Upload のローカルの痕跡をすべて消去して最初からやり直します：設定、保存した PS5 とそのペアリング、コレクション、保存したサーバーとそのパスワード、バックポート用ライブラリ、インストール履歴、ジョブとイベント、アクティビティ / キューの履歴、ログ、ペイロードのキャッシュ、クラッシュレポート。PS5 上のものには影響しません。上の「バックアップ / 復元」は、ペアリング、コレクション、サーバーのパスワード、バックポート用ライブラリを対象にしません。",
saves_backup_usb_tooltip_v2: "このセーブを、設定で指定したセーブのパス（PS5 の USB ドライブ）に zip で保存します。いったんこのコンピューターにコピーして zip にしてから送り返すので、アプリを開いたままにしてください。こちらのコピーは後で削除されます。",
saves_description_browser: "PS5 上のセーブデータ（ゲームごとに 1 項目）。セーブを .zip にバックアップしたり復元したりするにはデスクトップアプリが必要です。ここでは一覧の確認とフォルダーを開くことができます。",
saves_restore_usb_tooltip_v2: "設定で指定したセーブのパスにある最新のバックアップからこのセーブを復元します。zip をこのコンピューターにコピーして展開し、PS5 に送り返すので、アプリを開いたままにしてください。現在のセーブは上書きされます。",
